namespace InventoryTracker.Api.Domain;

/// <summary>
/// One raw material requested by a complementary order. Table <c>ComplementaryOrderLines</c>.
/// </summary>
public class ComplementaryOrderLine
{
    /// <summary>Primary key, generated by the database.</summary>
    public int Id { get; set; }

    /// <summary>Foreign key to the complementary order. A raw material appears at most once per complementary order.</summary>
    public int ComplementaryOrderNumber { get; set; }

    /// <summary>The complementary order, when loaded.</summary>
    public ComplementaryOrder ComplementaryOrder { get; set; } = null!;

    /// <summary>Position, as submitted.</summary>
    public int LineNo { get; set; }

    /// <summary>Foreign key to the raw material, which must be on the parent order (US-16).</summary>
    public int RawMaterialId { get; set; }

    /// <summary>The raw material, when loaded.</summary>
    public Item RawMaterial { get; set; } = null!;

    /// <summary>R: the amount requested; greater than 0. The send range is based on it (AC-18.1).</summary>
    public decimal RequestedAmount { get; set; }

    /// <summary>The quantity actually sent, set when the complementary order is Sent (US-18).</summary>
    public decimal? SentQuantity { get; set; }
}
